      "id": "2027892491522134053",
      "text": "as it was foretold https://t.co/ROFdZomBxL https://t.co/tDacnuCqLZ",
      "author_name": "Visakan Veerasamy",
      "author_handle": "@visakanv",
      "created_at": "2026-02-28T23:43:41.000Z",
